/* Original Dorian harp/flute score and synthesized weather. No audio downloads. */
(()=>{'use strict';
let ctx=null,music=null,effects=null,weatherNodes=[],timer=null,nextBeat=0,beat=0,enabled=false,condition='clear',indoors=false,lastThunder=0;
const melody=[62,69,74,76,77,76,74,69,67,69,72,74,76,74,69,65,62,65,69,72,74,72,69,67,65,67,69,74,72,69,65,62];
const noise=()=>{const b=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),d=b.getChannelData(0);let brown=0;for(let i=0;i<d.length;i++){const white=Math.random()*2-1;brown=(brown+.02*white)/1.02;d[i]=.55*white+.45*brown*3.5}return b};
function tone(midi,when,length,instrument='harp',volume=.12){if(!ctx||!music)return;const o=ctx.createOscillator(),g=ctx.createGain(),filter=ctx.createBiquadFilter();o.frequency.value=440*Math.pow(2,(midi-69)/12);o.type=instrument==='flute'?'sine':'triangle';filter.type='lowpass';filter.frequency.value=instrument==='flute'?1800:2400;g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(volume,when+(instrument==='flute'?.12:.012));g.gain.exponentialRampToValueAtTime(.0001,when+length);o.connect(filter).connect(g).connect(music);o.start(when);o.stop(when+length+.05);o.onended=()=>{o.disconnect();g.disconnect();filter.disconnect()}}
function tick(){if(!ctx||!enabled||document.hidden)return;while(nextBeat<ctx.currentTime+.2){const tension=!!document.getElementById('expSearch');const forest=globalThis.ELDORIA_CITY?.getLocation().district==='forest';const note=melody[beat%melody.length]-(tension?12:0);if(beat%8!==7)tone(note,nextBeat,.9,forest?'flute':'harp',tension?.045:.08);if(window.ELDORIA_PROMISE?.active&&beat%8===0)tone(melody[beat%melody.length]+12,nextBeat+.18,2.1,'flute',.045);if(beat%4===0){const roots=[50,48,53,55],root=roots[Math.floor(beat/8)%4];[0,7,12].forEach((n,i)=>tone(root+n,nextBeat+i*.12,2.6,'harp',.035))}beat++;nextBeat+=60/76}if(condition==='thunderstorm'&&ctx.currentTime-lastThunder>13+Math.random()*8){lastThunder=ctx.currentTime;rumble();window.dispatchEvent(new Event('eldoria-thunder'))}if(condition==='sleet'&&Math.random()<.2)weatherTap()}
function clearWeather(){for(const n of weatherNodes){try{n.stop?.()}catch{}try{n.disconnect()}catch{}}weatherNodes=[]}
function weather(type,inside){condition=type;indoors=inside;if(!ctx)return;clearWeather();if(type==='clear')return;const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=noise();source.loop=true;const wind=['snow','snowstorm','blizzard'].includes(type);filter.type=wind?'lowpass':'highpass';filter.frequency.value=wind?(type==='blizzard'?1400:650):type==='sleet'?3200:1100;const levels={rain:.22,sleet:.19,snow:.045,thunderstorm:.34,snowstorm:.2,blizzard:.36};gain.gain.value=(levels[type]||.1)*(inside?.28:1);source.connect(filter).connect(gain).connect(effects);source.start();weatherNodes.push(source,filter,gain);if(wind){const lfo=ctx.createOscillator(),depth=ctx.createGain();lfo.frequency.value=type==='blizzard'?.19:.08;depth.gain.value=filter.frequency.value*.35;lfo.connect(depth).connect(filter.frequency);lfo.start();weatherNodes.push(lfo,depth)}lastThunder=ctx.currentTime-8}
function rumble(){if(!ctx)return;const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),g=ctx.createGain();source.buffer=noise();source.loop=true;filter.type='lowpass';filter.frequency.value=180;const now=ctx.currentTime;g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(indoors?.12:.4,now+.4);g.gain.exponentialRampToValueAtTime(.0001,now+5);source.connect(filter).connect(g).connect(effects);source.start();source.stop(now+5.1);source.onended=()=>{source.disconnect();filter.disconnect();g.disconnect()}}
function weatherTap(){if(!ctx)return;const o=ctx.createOscillator(),g=ctx.createGain(),now=ctx.currentTime;o.type='sine';o.frequency.value=1400+Math.random()*1900;g.gain.setValueAtTime(indoors?.009:.025,now);g.gain.exponentialRampToValueAtTime(.0001,now+.035);o.connect(g).connect(effects);o.start();o.stop(now+.04);o.onended=()=>{o.disconnect();g.disconnect()}}
async function setEnabled(on,settings){enabled=!!on;if(!on){clearInterval(timer);timer=null;clearWeather();if(ctx){const old=ctx;ctx=null;music=effects=null;await old.close()}return false}const C=window.AudioContext||window.webkitAudioContext;if(!C){enabled=false;return false}if(!ctx){ctx=new C();music=ctx.createGain();effects=ctx.createGain();music.connect(ctx.destination);effects.connect(ctx.destination);nextBeat=ctx.currentTime+.08;beat=0;weather(condition,indoors)}volumes(settings);await ctx.resume();if(!timer)timer=setInterval(tick,100);return true}
function volumes(a){if(!ctx)return;music.gain.setTargetAtTime(a.musicVolume,ctx.currentTime,.15);effects.gain.setTargetAtTime(a.effectsVolume,ctx.currentTime,.15)}
function gesture(){if(!ctx||!enabled)return;weatherTap()}
document.addEventListener('visibilitychange',()=>{if(!ctx)return;if(document.hidden)ctx.suspend();else if(enabled){nextBeat=ctx.currentTime+.1;ctx.resume()}});
window.EldoriaSound={setEnabled,weather,volumes,gesture,get active(){return enabled&&!!ctx},get state(){return ctx?.state||'off'}};
})();
